#include <iostream>
#include <memory>
#include <utility>

struct Interrupcion { int etapa; };
struct Balance {
    int recursos_vivos = 0;
    int bases_completadas = 0;
    int derivadas_completadas = 0;
    int recursos_completados = 0;
    int bases_destruidas = 0;
    int derivadas_destruidas = 0;
    int recursos_destruidos = 0;
};

class Recurso {
public:
    Recurso(int valor, int fallo, Balance& balance) : valor_{valor}, balance_{balance} {
        if (fallo != 0) { throw Interrupcion{fallo}; }
        ++balance_.recursos_vivos;
        ++balance_.recursos_completados;
    }
    Recurso(const Recurso&) = delete;
    Recurso& operator=(const Recurso&) = delete;
    ~Recurso() noexcept { --balance_.recursos_vivos; ++balance_.recursos_destruidos; }
    int valor() const noexcept { return valor_; }
private:
    int valor_;
    Balance& balance_;
};

class Medida {
public:
    Medida(int numero, int modo, Balance& balance)
        : numero_{std::make_unique<Recurso>(numero, 0, balance)}, balance_{balance} {
        if (modo == 1) { throw Interrupcion{1}; }
        ++balance_.bases_completadas;
    }
    virtual ~Medida() noexcept { ++balance_.bases_destruidas; }
    Medida(const Medida&) = delete;
    Medida& operator=(const Medida&) = delete;
    int numero() const noexcept { return numero_->valor(); }
    virtual void escribir(std::ostream& salida) const { salida << "Numero:" << numero(); }
private:
    std::unique_ptr<Recurso> numero_;
    Balance& balance_;
};

class MedidaIdentificada : public Medida {
public:
    MedidaIdentificada(int numero, int codigo, int modo, Balance& balance)
        : Medida{numero, modo, balance},
          codigo_{std::make_unique<Recurso>(codigo, modo == 2 ? 2 : 0, balance)}, balance_{balance} {
        if (modo == 3) { throw Interrupcion{3}; }
        ++balance_.derivadas_completadas;
    }
    ~MedidaIdentificada() noexcept override { ++balance_.derivadas_destruidas; }
    int codigo() const noexcept { return codigo_->valor(); }
    void escribir(std::ostream& salida) const override {
        Medida::escribir(salida);
        salida << ";Codigo:" << codigo();
    }
private:
    std::unique_ptr<Recurso> codigo_;
    Balance& balance_;
};

void sustituir(std::unique_ptr<Medida>& destino, int numero, int codigo, int modo, Balance& balance) {
    // Prepara la medida nueva antes de cambiar el propietario recibido.
    (void)destino;
    (void)numero;
    (void)codigo;
    (void)modo;
    (void)balance;
}

int main() {
    int anterior_numero = 0, anterior_codigo = 0, numero = 0, codigo = 0, modo = 0;
    if (!(std::cin >> anterior_numero >> anterior_codigo >> numero >> codigo >> modo) || modo < 0 || modo > 3) { return 1; }
    Balance balance;
    {
        std::unique_ptr<Medida> destino = std::make_unique<MedidaIdentificada>(anterior_numero, anterior_codigo, 0, balance);
        int etapa = 0;
        try {
            sustituir(destino, numero, codigo, modo, balance);
        } catch (const Interrupcion& error) {
            etapa = error.etapa;
        }
        std::cout << "Resultado:";
        if (etapa == 0) { std::cout << "Aceptado\n"; }
        else { std::cout << "Rechazado:" << etapa << '\n'; }
        std::cout << "Destino:";
        if (destino) { destino->escribir(std::cout); }
        else { std::cout << "Vacio"; }
        std::cout << '\n' << "Vivos:" << balance.recursos_vivos << '\n'
                  << "Completados:" << balance.bases_completadas << ',' << balance.derivadas_completadas << ',' << balance.recursos_completados << '\n'
                  << "Destruidos:" << balance.bases_destruidas << ',' << balance.derivadas_destruidas << ',' << balance.recursos_destruidos << '\n';
    }
    std::cout << "FinalVivos:" << balance.recursos_vivos << '\n'
              << "FinalDestruidos:" << balance.bases_destruidas << ',' << balance.derivadas_destruidas << ',' << balance.recursos_destruidos;
    return 0;
}

